Bash(curl -s "https://openrouter.ai/api/v1/models" | node -e "
const chunks = [];
process.stdin.on\('data', c => chunks.push\(c\)\);
process.stdin.on\('end', \(\) => {
  const data = JSON.parse\(Buffer.concat\(chunks\).toString\(\)\);
  const models = data.data || [];
  const ds = models.filter\(m => m.id.toLowerCase\(\).includes\('deepseek'\)\);
  ds.forEach\(m => {
    const p = m.pricing || {};
    const free = p.prompt === '0' && p.completion === '0';
    console.log\('ID:', m.id\);
    console.log\('  Context:', m.context_length\);
    console.log\('  Prompt price:', p.prompt, '/token'\);
    console.log\('  Completion price:', p.completion, '/token'\);
    console.log\('  Free:', free\);
    console.log\('  Max completion:', m.top_provider?.max_completion_tokens || 'N/A'\);
    console.log\(\);
  }\);
  console.log\('Total DeepSeek models:', ds.length\);
}\);
")

Bash(curl -s "https://openrouter.ai/api/v1/models" | node -e "
const chunks = [];
process.stdin.on\('data', c => chunks.push\(c\)\);
process.stdin.on\('end', \(\) => {
  const data = JSON.parse\(Buffer.concat\(chunks\).toString\(\)\);
  const models = data.data || [];
  const free = models.filter\(m => {
    const p = m.pricing || {};
    return p.prompt === '0' && p.completion === '0';
  }\);
  console.log\('Total free models:', free.length\);
  free.forEach\(m => {
    console.log\('  -', m.id, '\(ctx:', m.context_length + '\)'\);
  }\);

  // Also check for deepseek free
  const dsFree = free.filter\(m => m.id.toLowerCase\(\).includes\('deepseek'\)\);
  console.log\('\\nFree DeepSeek models:', dsFree.length\);
  if\(dsFree.length === 0\) console.log\('  \(none\)'\);
}\);
")

Bash(curl -s "https://openrouter.ai/api/v1/models" | node -e "
const chunks = [];
process.stdin.on\('data', c => chunks.push\(c\)\);
process.stdin.on\('end', \(\) => {
  const data = JSON.parse\(Buffer.concat\(chunks\).toString\(\)\);
  const models = data.data || [];
  // check if deepseek/deepseek-chat:free exists
  const dsFree = models.filter\(m => m.id.toLowerCase\(\).includes\('deepseek'\) && m.id.includes\(':free'\)\);
  console.log\('DeepSeek :free models:', dsFree.length\);
  dsFree.forEach\(m => console.log\(' ', m.id\)\);

  // Show how free models are named
  const freeModels = models.filter\(m => m.id.includes\(':free'\)\).slice\(0, 5\);
  console.log\('\\\\nSample :free models:'\);
  freeModels.forEach\(m => console.log\(' ', m.id\)\);
}\);
")

